python3 -c "
import importlib
for mod in ['pypdf', 'reportlab', 'fpdf', 'fpdf2', 'pdfplumber', 'PyPDF2', 'pikepdf', 'weasyprint', 'matplotlib', 'PIL']:
    try:
        m = importlib.import_module(mod)
        print(f'{mod}: AVAILABLE ({getattr(m, \"__version__\", \"?\")})')
    except ImportError:
        print(f'{mod}: not available')
"
